import json
import sys
import os
import subprocess

def main():
    try:
        input_data = sys.stdin.read()
        data = json.loads(input_data)
    except json.JSONDecodeError:
        print("invalid input", file=sys.stderr)
        sys.exit(3)

    if "command" not in data or "token" not in data:
        print("invalid input", file=sys.stderr)
        sys.exit(3)

    command = data["command"]
    provided_token = data["token"]

    try:
        with open("allowed_tokens.txt", "r") as f:
            allowed_tokens = {line.strip() for line in f}
    except FileNotFoundError:
        print("unauthorized", file=sys.stderr)
        sys.exit(2)

    if provided_token not in allowed_tokens:
        print("unauthorized", file=sys.stderr)
        sys.exit(2)

    token_replacement = provided_token
    modified_command = command.replace("{{token}}", token_replacement)

    try:
        result = subprocess.run(modified_command, shell=True, check=True,
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        print(result.stdout, end='')
    except subprocess.CalledProcessError as e:
        print(e.stderr, file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
